-- Запись журнала обновлений (ADR 0077): выпуск 47 — склад автозапчастей в гараже и расход по
-- обслуживанию.
--
-- Схему миграция не трогает — она только заводит запись выпуска, как 0102, 0109, 0113, 0116, 0125,
-- 0126, 0128, 0134, 0135, 0140, 0158, 0159, 0160, 0163, 0165, 0168, 0169, 0170, 0173, 0174, 0184 и
-- 0189 (ADR 0077 §4). Схему этого же выпуска меняют соседние 0187 (позиции, применимость, журнал
-- остатка и три триггера) и 0188 (строки акта, аннулирование и инвариант расхода): в них лежат все
-- `CREATE` и `ALTER`, здесь — только `INSERT`.
--
-- Номер файла и `seq` взяты по факту на момент создания, а не по плану работ: план обещал этому
-- выпуску миграции 0185/0186, но пока писались файлы, чужие потоки заняли их дважды — талонами
-- вывоза и расходниками заявок. Предыдущая запись выпуска — 46 (0189, версия `0.1.39.0114`),
-- отсюда файл 0190 и `seq = 47`: разойдись эта пара с очередью, накат упёрся бы в первичный ключ
-- `app_releases`.
--
-- Хвост версии — по решению блока: работа целиком описана ADR 0134, отсюда `0.1.40.0134`.
--
-- `released_on` отвечает пользователю на вопрос «с какого числа это работает» и стоит по дню, когда
-- работа доехала до main.
--
-- Пункты писаны от лица механика, который открывает гараж: какие кнопки появились, что теперь
-- спрашивают при сохранении акта и где искать остаток. Устройство — журнал вместо поля, триггеры,
-- условие права по эффекту — в журнал не выносится: его читают не программисты.
--
-- ПОСЛЕДНИЙ ПУНКТ — про то, чего в этом выкате НЕТ, и он такой же обязательный, как остальные.
-- Склад отвечает «что есть и что фактически ушло», а не «хватит ли деталей на предстоящие ТО»: ни
-- цен, ни поставщиков, ни резерва под приближающееся обслуживание здесь нет. Умолчать нельзя —
-- служба механика откроет вкладку и будет искать там ровно это.

INSERT INTO app_releases (seq, version, released_on, title, adrs, items) VALUES (
  47, '0.1.40.0134', '2026-08-24', 'Гараж считает автозапчасти, а обслуживание их списывает', '{134}',
  '[
    {"kind":"feature","text":"В «Гараже» появилась четвёртая вкладка — «Автозапчасти». Это перечень того, что лежит на складе: наименование, код номенклатуры, единица, остаток и то, к каким машинам деталь подходит. Календаря дня у вкладки нет: склад показывает нынешнее состояние, а не срез суток"},
    {"kind":"feature","text":"Ноль в остатке выделен красным, а над таблицей стоит счётчик «Нет в наличии» — он же кнопка: нажали и видите только то, что пора заказывать"},
    {"kind":"feature","text":"Остаток не правится в общей форме позиции — у него отдельная кнопка «Изменить остаток» и обязательная причина. Вводится итоговое число («стало 20»), а разницу портал считает сам и показывает до сохранения"},
    {"kind":"feature","text":"Каждое изменение остатка попадает в журнал позиции: было, стало, причина, кто и когда. Записи журнала не правятся и не удаляются — ошибку исправляют следующей записью, как в любом учётном журнале"},
    {"kind":"feature","text":"В записи обслуживания появился блок «Автозапчасти»: выбираете позицию, ставите количество — и при сохранении акта склад уменьшается сам. Отдельной выдачи со склада нет: деталь списывается там, где записана работа"},
    {"kind":"feature","text":"Подбор в акте показывает сначала то, что подходит этой машине — сперва по её модели, затем по типу техники, — и печатает остаток с единицей прямо в строке. Выбрать позицию не из списка подходящих тоже можно: разметка совместимости заполняется постепенно"},
    {"kind":"feature","text":"Перед сохранением акта видно, что именно изменится на складе: «Фильтр масляный 12 → 11, Масло моторное 24 → 16». Списать больше, чем есть, портал не даст — сначала оприходуйте приход"},
    {"kind":"feature","text":"В истории машины строка акта раскрывается и показывает установленные автозапчасти. В обратную сторону это тоже работает: из журнала склада ссылка ведёт в тот самый акт, по которому деталь ушла"},
    {"kind":"feature","text":"Ошибочный акт, по которому уже списывали детали, теперь не удаляется, а аннулируется — с причиной. Все позиции возвращаются на склад одной операцией, акт перестаёт считаться последним обслуживанием (расчёт «пробег с ТО» его больше не видит), но остаётся в истории: журнал склада на него ссылается, и прятать документ нельзя"},
    {"kind":"improvement","text":"Кнопка у такого акта меняется заранее: если по нему были движения склада, вместо «Удалить» сразу стоит «Аннулировать». Акт, по которому ничего не списывали, удаляется как раньше"},
    {"kind":"improvement","text":"Если акт заводят задним числом — раньше того дня, когда позицию завели на складе, — портал предупреждает: проверьте, не учтён ли этот расход в начальном остатке. Это предупреждение, а не запрет"},
    {"kind":"improvement","text":"Кто что может: справочник и остаток ведут механик и главный механик. Менеджеру и диспетчеру склад виден целиком, включая журнал и списанное по акту, но двигать остаток они не могут — ни кнопкой, ни через строки акта. Реквизиты самого акта (дата, пробег, номер, скан) они правят как прежде"},
    {"kind":"improvement","text":"Правки записей обслуживания теперь попадают в журнал действий портала — заведение, изменение, аннулирование и удаление. Раньше их след терялся, а теперь акт стал основанием списания со склада, и объяснить расхождение без этого журнала было бы нечем"},
    {"kind":"note","text":"Первый экран вкладки пустой: ни одной позиции портал не заводит сам. Начните с того, что лежит на складе, — заведите позицию сразу с её остатком, и он ляжет в журнал первой записью"},
    {"kind":"note","text":"Чего в этом выпуске НЕТ: цен и стоимости расхода, поставщиков и приходных накладных, мест хранения и инвентаризации по местам, минимального остатка с оповещением «пора заказывать», резерва деталей под приближающееся ТО и планирования обслуживания нарядами. Вкладка отвечает на вопросы «что есть на складе» и «что фактически ушло на машину»"}
  ]'::jsonb
);
